using Brutal.VulkanApi;
using Brutal.VulkanApi.Abstractions;

namespace FullThrust.Game.Rendering;

// A sampled RGBA8 texture, or texture array, with a full mip chain generated by blits at upload. Array layers are packed one after another in the source pixels.
public sealed class GpuTexture : IDisposable {

    private readonly ImageEx _image;
    private readonly ImageViewEx _view;

    public GpuTexture(GpuUploader uploader, string name, ReadOnlySpan<byte> rgba, int width, int height, bool srgb, int layers = 0) {

        var format = srgb ? VkFormat.R8G8B8A8SRGB : VkFormat.R8G8B8A8UNorm;

        MipLevels = 1 + (int)Math.Floor(Math.Log2(Math.Max(width, height)));
        Layers = Math.Max(1, layers);

        var image = uploader.Device.CreateImage(new ImageEx.CreateInfo {

            Name = name,
            ImageType = VkImageType._2D,
            ImageFormat = format,
            ImageExtent = new VkExtent3D { Width = width, Height = height, Depth = 1 },
            ImageMipLevels = MipLevels,
            ImageArrayLayers = Layers,
            ImageSamples = VkSampleCountFlags._1Bit,
            ImageTiling = VkImageTiling.Optimal,
            ImageUsage = VkImageUsageFlags.TransferSrcBit | VkImageUsageFlags.TransferDstBit | VkImageUsageFlags.SampledBit,
            AllocRequiredProperties = VkMemoryPropertyFlags.DeviceLocalBit,

        });

        _image = image;
        _view = image.CreateImageView(layers > 0 ? VkImageViewType._2DArray : VkImageViewType._2D, image.GetFullRange(VkImageAspectFlags.ColorBit), null);

        Record(uploader, image.VkImage, uploader.Stage(rgba).VkBuffer, width, height);

    }

    public int MipLevels { get; }

    public int Layers { get; }

    public VkImageView View => _view.VkImageView;

    private void Record(GpuUploader uploader, VkImage image, VkBuffer staging, int width, int height) {

        var cmd = uploader.Commands;

        Barrier(cmd, image, 0, MipLevels, VkImageLayout.Undefined, VkImageLayout.TransferDstOptimal, VkAccessFlags.None, VkAccessFlags.TransferWriteBit, VkPipelineStageFlags.TopOfPipeBit, VkPipelineStageFlags.TransferBit);

        cmd.CopyBufferToImage(staging, image, VkImageLayout.TransferDstOptimal, [

            new VkBufferImageCopy {

                ImageSubresource = new VkImageSubresourceLayers { AspectMask = VkImageAspectFlags.ColorBit, LayerCount = Layers },
                ImageExtent = new VkExtent3D { Width = width, Height = height, Depth = 1 },

            },

        ]);

        for (var level = 1; level < MipLevels; level++) {

            var sourceWidth = Math.Max(1, width >> (level - 1));
            var sourceHeight = Math.Max(1, height >> (level - 1));

            Barrier(cmd, image, level - 1, 1, VkImageLayout.TransferDstOptimal, VkImageLayout.TransferSrcOptimal, VkAccessFlags.TransferWriteBit, VkAccessFlags.TransferReadBit, VkPipelineStageFlags.TransferBit, VkPipelineStageFlags.TransferBit);

            var blit = new VkImageBlit {

                SrcSubresource = new VkImageSubresourceLayers { AspectMask = VkImageAspectFlags.ColorBit, MipLevel = level - 1, LayerCount = Layers },
                DstSubresource = new VkImageSubresourceLayers { AspectMask = VkImageAspectFlags.ColorBit, MipLevel = level, LayerCount = Layers },

            };

            blit.SrcOffsets[1] = new VkOffset3D { X = sourceWidth, Y = sourceHeight, Z = 1 };
            blit.DstOffsets[1] = new VkOffset3D { X = Math.Max(1, sourceWidth / 2), Y = Math.Max(1, sourceHeight / 2), Z = 1 };

            cmd.BlitImage(image, VkImageLayout.TransferSrcOptimal, image, VkImageLayout.TransferDstOptimal, [blit], VkFilter.Linear);

            Barrier(cmd, image, level - 1, 1, VkImageLayout.TransferSrcOptimal, VkImageLayout.ShaderReadOnlyOptimal, VkAccessFlags.TransferReadBit, VkAccessFlags.ShaderReadBit, VkPipelineStageFlags.TransferBit, VkPipelineStageFlags.FragmentShaderBit);

        }

        Barrier(cmd, image, MipLevels - 1, 1, VkImageLayout.TransferDstOptimal, VkImageLayout.ShaderReadOnlyOptimal, VkAccessFlags.TransferWriteBit, VkAccessFlags.ShaderReadBit, VkPipelineStageFlags.TransferBit, VkPipelineStageFlags.FragmentShaderBit);

    }

    private void Barrier(CommandBuffer cmd, VkImage image, int baseLevel, int levels, VkImageLayout from, VkImageLayout to, VkAccessFlags srcAccess, VkAccessFlags dstAccess, VkPipelineStageFlags srcStage, VkPipelineStageFlags dstStage) {

        cmd.PipelineBarrier(srcStage, dstStage, VkDependencyFlags.None, [], [], [

            new VkImageMemoryBarrier {

                SrcAccessMask = srcAccess,
                DstAccessMask = dstAccess,
                OldLayout = from,
                NewLayout = to,
                SrcQueueFamilyIndex = VK.QUEUE_FAMILY_IGNORED,
                DstQueueFamilyIndex = VK.QUEUE_FAMILY_IGNORED,
                Image = image,
                SubresourceRange = new VkImageSubresourceRange { AspectMask = VkImageAspectFlags.ColorBit, BaseMipLevel = baseLevel, LevelCount = levels, LayerCount = Layers },

            },

        ]);

    }

    public void Dispose() {

        _view.Dispose();
        _image.Dispose();

    }

}
